import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// GEMM kernel with split-K reduction.
// A: (M,K) row-major, stride (K,1)
// B: (K,N) row-major, stride (N,1)
// C: (M,N) row-major, stride (N,1), accumulated via atomicAdd across K-splits.
template <class TA, class TB, class TC>
__global__ static void
gemm_splitk_device(int M, int N, int K,
                    TA const* A,
                    TB const* B,
                    TC      * C,
                    int split_k, int k_tiles_total)
{
  constexpr int BLK_M = 128;
  constexpr int BLK_N = 128;
  constexpr int BLK_K = 8;

  // Represent full tensors.
  // mA: (M,K) with A row-major stride (K,1)
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
  // mB viewed as (N,K): mB(n,k) = B[k*N + n]  => stride (1, N)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N));
  // mC: (M,N) row-major stride (N,1)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));

  auto cta_tiler = make_shape(Int<BLK_M>{}, Int<BLK_N>{}, Int<BLK_K>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{});  // (BLK_M, BLK_K, k_tiles_total)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X,_1, _1>{});  // (BLK_N, BLK_K, k_tiles_total)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,  X>{});  // (BLK_M, BLK_N)

  __shared__ TA smemA[BLK_M * BLK_K];
  __shared__ TB smemB[BLK_N * BLK_K];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<BLK_M>{}, Int<BLK_K>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<BLK_N>{}, Int<BLK_K>{}));

  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  // Split the K-tile range among blockIdx.z
  int k_tile_start = (int)((long long)blockIdx.z * k_tiles_total / split_k);
  int k_tile_end   = (int)((long long)(blockIdx.z + 1) * k_tiles_total / split_k);

  for (int k_tile = k_tile_start; k_tile < k_tile_end; ++k_tile) {
    copy(tAgA(_, _, k_tile), tAsA);
    copy(tBgB(_, _, k_tile), tBsB);

    cp_async_fence();
    cp_async_wait<0>();
    __syncthreads();

    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  // Atomic accumulation into global C (needed because of split-K reduction)
  CUTE_UNROLL
  for (int i = 0; i < size(tCrC); ++i) {
    atomicAdd(&tCgC(i), tCrC(i));
  }
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int64_t M = A.size(0);
  int64_t K = A.size(1);
  int64_t K2 = B.size(0);
  int64_t N = B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions of A and B must match");

  constexpr int BLK_M = 128;
  constexpr int BLK_N = 128;
  constexpr int BLK_K = 8;

  TORCH_CHECK(M % BLK_M == 0, "M must be divisible by 128 for this kernel");
  TORCH_CHECK(N % BLK_N == 0, "N must be divisible by 128 for this kernel");
  TORCH_CHECK(K % BLK_K == 0, "K must be divisible by 8 for this kernel");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::zeros({M, N}, A.options());

  int64_t k_tiles_total = K / BLK_K;

  // Find largest power-of-two split (up to 256) that evenly divides k_tiles_total
  int64_t split_k = 1;
  const int64_t max_split = 256;
  while (split_k < max_split && (k_tiles_total % (split_k * 2) == 0)) {
    split_k *= 2;
  }

  dim3 dimBlock(256);
  dim3 dimGrid((unsigned)(M / BLK_M), (unsigned)(N / BLK_N), (unsigned)split_k);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gemm_splitk_device<float, float, float><<<dimGrid, dimBlock, 0, stream>>>(
      (int)M, (int)N, (int)K,
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      (int)split_k, (int)k_tiles_total);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm_splitk_device launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemm_ext = load_inline(
    name="cute_gemm_splitk_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B) with a large K dimension,
    implemented using a custom split-K tiled GEMM kernel written with CUTE.
    """
    def __init__(self) -> None:
        super().__init__()
        self._ext = cute_gemm_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A.contiguous(), B.contiguous())

